#!/usr/bin/env node
// Renders spec/builtins.json — the authored builtin manifest — into every host
// and into docs/reference/builtins.md.
//
//     node tools/gen-builtins.mjs            write the generated files
//     node tools/gen-builtins.mjs --check    validate and diff, write nothing
//
// The renderings ARE committed, like the SQL map (tools/gen-sql-map.mjs): a
// PHP, Python, C++ or Lisp consumer must never need Node. Each host reads its
// rendering at startup as a native table — no JSON, no reflection — and its
// `define` refuses a builtin whose min/max/lazy/binds disagree with it, takes
// the extra arity rule from it, and refuses to finish registration with a
// manifest name it never defined. Staleness is caught by --check, which
// tools/check-generated.sh runs from tools/check.sh.
//
// Everything spec/builtins.md promises about the format is enforced here, so
// no host has to defend against a malformed manifest. A validation failure is
// a non-zero exit naming the entry and the key.

import { readFileSync } from 'node:fs';
import { genArgs, writeOrCheck, jsStr, pyStr, phpStr, cppStr, lispStr } from './gen-lib.mjs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const USAGE = `usage: node tools/gen-builtins.mjs            write the generated files
       node tools/gen-builtins.mjs --check    validate and diff, write nothing`;
const { check } = genArgs('gen-builtins', USAGE);
const SOURCE = 'spec/builtins.json';

const OUTPUTS = {
  js: 'js/src/_builtin_manifest.mjs',
  python: 'python/sel/_builtin_manifest.py',
  php: 'php/src/BuiltinManifest.php',
  cpp: 'cpp/sel_builtin_manifest.hpp',
  lisp: 'lisp/src/builtin-manifest.lisp',
  go: 'go/internal/manifest/builtins.go',
  rust: 'rust/src/manifest/builtins.rs',
  docs: 'docs/reference/builtins.md',
};

const HEADER = `GENERATED by tools/gen-builtins.mjs from ${SOURCE} — do not edit; edit the manifest and regenerate.`;

// ---------------------------------------------------------------------------
// Validation (spec/builtins.md).

function fail(msg) {
  process.stderr.write(`gen-builtins: ${msg}\n`);
  process.exit(1);
}

const ENTRY_KEYS = new Set(['arity', 'lazy', 'binds', 'forms', 'pipeline', 'regex', 'sql', 'yieldsList', 'signatures', 'spec']);
const ROLES = new Set(['source', 'outer', 'binder', 'body', 'key', 'proj', 'pred']);
const INNER = new Set(['body', 'key', 'proj', 'pred']);
const WHEN_KINDS = new Set(['name', 'text']);
const ARITY_KEYS = new Set(['min', 'max', 'allowed', 'parity', 'message']);

function load() {
  const doc = JSON.parse(readFileSync(resolve(ROOT, SOURCE), 'utf8'));
  const builtins = doc.builtins;
  if (!builtins || typeof builtins !== 'object') fail('"builtins" must be an object');
  const names = Object.keys(builtins);
  const sorted = [...names].sort();
  for (let i = 0; i < names.length; i++) {
    if (names[i] !== sorted[i]) fail(`entries must be sorted by name: ${names[i]} is out of order`);
  }
  const out = [];
  for (const name of names) {
    const e = builtins[name];
    const where = (k) => `${name}.${k}`;
    if (!/^[A-Z][A-Z0-9_]*$/.test(name)) fail(`${name}: a builtin name is upper-case ASCII`);
    for (const k of Object.keys(e)) if (!ENTRY_KEYS.has(k)) fail(`${where(k)}: unknown key`);
    const a = e.arity;
    if (!a || typeof a !== 'object') fail(`${where('arity')}: required`);
    for (const k of Object.keys(a)) if (!ARITY_KEYS.has(k)) fail(`${where('arity.' + k)}: unknown key`);
    if (!Number.isInteger(a.min) || a.min < 0) fail(`${where('arity.min')}: a non-negative integer`);
    const variadic = a.max === 'variadic';
    if (!variadic && (!Number.isInteger(a.max) || a.max < a.min)) {
      fail(`${where('arity.max')}: an integer >= min, or "variadic"`);
    }
    if (a.allowed !== undefined && a.parity !== undefined) fail(`${where('arity')}: allowed and parity are exclusive`);
    if (a.allowed !== undefined) {
      if (variadic) fail(`${where('arity.allowed')}: needs a numeric max`);
      if (!Array.isArray(a.allowed) || a.allowed.length < 2) fail(`${where('arity.allowed')}: at least two counts`);
      for (let i = 0; i < a.allowed.length; i++) {
        const c = a.allowed[i];
        if (!Number.isInteger(c) || c < a.min || c > a.max) fail(`${where('arity.allowed')}: ${c} is outside min..max`);
        if (i > 0 && c <= a.allowed[i - 1]) fail(`${where('arity.allowed')}: counts ascend, no repeats`);
      }
      if (a.allowed.length === a.max - a.min + 1) fail(`${where('arity.allowed')}: lists every count in the range — drop it`);
    }
    if (a.parity !== undefined && a.parity !== 'odd' && a.parity !== 'even') fail(`${where('arity.parity')}: "odd" or "even"`);
    const hasRule = a.allowed !== undefined || a.parity !== undefined;
    if (hasRule) {
      if (typeof a.message !== 'string' || !a.message.includes('{count}')) {
        fail(`${where('arity.message')}: required with a rule, and must contain {count}`);
      }
    } else if (a.message !== undefined) {
      fail(`${where('arity.message')}: only with allowed or parity`);
    }
    for (const k of ['lazy', 'binds']) {
      if (e[k] !== undefined && e[k] !== true) fail(`${where(k)}: true or absent`);
    }
    if (e.binds && !e.lazy) fail(`${where('binds')}: a binding builtin is lazy`);
    // Binding forms: one entry per accepted count, in the order the evaluator
    // tries them; a `when` guard disambiguates counts that admit two forms and
    // the last form for a count carries none.
    let forms = null;
    if (e.forms !== undefined) {
      if (!e.binds) fail(`${where('forms')}: only a binding builtin has forms`);
      if (!Array.isArray(e.forms) || e.forms.length === 0) fail(`${where('forms')}: a non-empty array`);
      forms = [];
      const allowed = (c) => c >= a.min && (variadic || c <= a.max) && (!a.allowed || a.allowed.includes(c))
        && (!a.parity || (c % 2 === 1) === (a.parity === 'odd'));
      const lastForCount = new Map();
      e.forms.forEach((f, i) => {
        const fw = `${where('forms')}[${i}]`;
        for (const k of Object.keys(f)) if (!['roles', 'when', 'binds'].includes(k)) fail(`${fw}.${k}: unknown key`);
        if (!Array.isArray(f.roles) || f.roles.length === 0) fail(`${fw}.roles: a non-empty array`);
        for (const r of f.roles) if (!ROLES.has(r)) fail(`${fw}.roles: unknown role "${r}"`);
        if (!allowed(f.roles.length)) fail(`${fw}: ${f.roles.length} arguments is not an accepted count`);
        if (f.roles.filter((r) => r === 'binder').length > 2) fail(`${fw}: at most two binders`);
        if (f.when !== undefined) {
          if (!Number.isInteger(f.when.arg) || f.when.arg < 0 || f.when.arg >= f.roles.length) fail(`${fw}.when.arg: an argument index`);
          if (!WHEN_KINDS.has(f.when.is)) fail(`${fw}.when.is: "name" or "text"`);
          if (Object.keys(f.when).length !== 2) fail(`${fw}.when: {arg, is}`);
        }
        if (!Array.isArray(f.binds) || f.binds.length === 0) fail(`${fw}.binds: the names bound inside, at least _K`);
        for (const b of f.binds) if (!/^_[A-Z0-9]*$/.test(b)) fail(`${fw}.binds: "${b}" is not an implicit binder name`);
        if (!f.binds.includes('_K')) fail(`${fw}.binds: _K is bound in every body`);
        lastForCount.set(f.roles.length, f.when === undefined);
        forms.push({ roles: f.roles, when: f.when ?? null, binds: f.binds });
      });
      for (const [count, unguarded] of lastForCount) {
        if (!unguarded) fail(`${where('forms')}: the last form with ${count} arguments must have no guard`);
      }
      for (let c = a.min; c <= (variadic ? a.min : a.max); c++) {
        if (allowed(c) && !lastForCount.has(c)) fail(`${where('forms')}: no form with ${c} arguments`);
      }
    } else if (e.binds) {
      fail(`${where('forms')}: a binding builtin declares its forms`);
    }
    // Classification (spec/builtins.md, "Classification"): facts the evaluator,
    // optimiser, planners and translators used to keep in lists of their own.
    let pipeline = null;
    if (e.pipeline !== undefined) {
      const p = e.pipeline;
      if (!p || typeof p !== 'object' || Object.keys(p).sort().join() !== 'keepsRows,sorts'
        || typeof p.keepsRows !== 'boolean' || typeof p.sorts !== 'boolean') {
        fail(`${where('pipeline')}: { keepsRows: bool, sorts: bool }`);
      }
      if (p.sorts && !p.keepsRows) fail(`${where('pipeline')}: a sort keeps its rows`);
      if (a.min < 1) fail(`${where('pipeline')}: a step's first argument is the rows`);
      if (e.yieldsList !== true) fail(`${where('yieldsList')}: a pipeline step yields a list`);
      pipeline = { keepsRows: p.keepsRows, sorts: p.sorts };
    }
    let regex = null;
    if (e.regex !== undefined) {
      const r = e.regex;
      const ok = (i) => Number.isInteger(i) && i >= 0 && (variadic || i < a.max);
      if (!r || typeof r !== 'object' || Object.keys(r).sort().join() !== 'flags,pattern' || !ok(r.pattern) || !ok(r.flags)) {
        fail(`${where('regex')}: { pattern, flags }, argument indexes`);
      }
      if (r.pattern >= a.min) fail(`${where('regex.pattern')}: the pattern is a required argument`);
      if (r.flags < a.min || r.flags !== (variadic ? -1 : a.max - 1)) fail(`${where('regex.flags')}: the flags are the last, optional argument`);
      if (e.lazy) fail(`${where('regex')}: a regex builtin is strict`);
      regex = { pattern: r.pattern, flags: r.flags };
    }
    let sql = null;
    if (e.sql !== undefined) {
      const q = e.sql;
      if (!q || typeof q !== 'object' || Object.keys(q).length === 0) fail(`${where('sql')}: a non-empty object`);
      for (const k of Object.keys(q)) if (!['numericArgs', 'binArg', 'boolArg'].includes(k)) fail(`${where('sql.' + k)}: unknown key`);
      if (e.lazy) fail(`${where('sql')}: only a strict builtin's arguments are typed`);
      let numeric = null;
      if (q.numericArgs !== undefined) {
        if (q.numericArgs === 'all') {
          if (!variadic) fail(`${where('sql.numericArgs')}: "all" is for a variadic builtin; list the indexes`);
          numeric = 'all';
        } else {
          if (!Array.isArray(q.numericArgs) || q.numericArgs.length === 0) fail(`${where('sql.numericArgs')}: a list of indexes or "all"`);
          q.numericArgs.forEach((i, k) => {
            if (!Number.isInteger(i) || i < 0 || (!variadic && i >= a.max)) fail(`${where('sql.numericArgs')}: ${i} is not an argument index`);
            if (k > 0 && i <= q.numericArgs[k - 1]) fail(`${where('sql.numericArgs')}: indexes ascend, no repeats`);
          });
          numeric = q.numericArgs;
        }
      }
      for (const k of ['binArg', 'boolArg']) if (q[k] !== undefined && q[k] !== true) fail(`${where('sql.' + k)}: true or absent`);
      sql = { numeric, bin: !!q.binArg, bool: !!q.boolArg };
    }
    if (e.yieldsList !== undefined && e.yieldsList !== true) fail(`${where('yieldsList')}: true or absent`);
    if (!Array.isArray(e.signatures) || e.signatures.length === 0) fail(`${where('signatures')}: at least one form`);
    for (const s of e.signatures) {
      if (typeof s !== 'string' || !s.startsWith(name + '(') || !s.endsWith(')')) {
        fail(`${where('signatures')}: "${s}" is not a ${name}(…) form`);
      }
    }
    if (typeof e.spec !== 'string' || !/^§\d+(\.\d+)*$/.test(e.spec)) fail(`${where('spec')}: "§n.m"`);
    out.push({
      name, min: a.min, max: variadic ? null : a.max,
      allowed: a.allowed ?? null, parity: a.parity ?? null, message: a.message ?? null,
      lazy: !!e.lazy, binds: !!e.binds, forms, signatures: e.signatures, spec: e.spec,
      pipeline, regex, sql, yieldsList: !!e.yieldsList,
    });
  }
  return out;
}

// ---------------------------------------------------------------------------
// Renderers. Every string literal goes through the host's own escaping.

// What a consumer needs from a role: where the argument is evaluated. The
// descriptive role names stay in the manifest and the docs.
const scopeOf = (role) => (role === 'binder' ? 'binder' : INNER.has(role) ? 'inner' : 'outer');


// The classification tables every host renders the same way (spec/builtins.md,
// "Classification").
function classificationComment(c) {
  return [
    `${c} Classification (spec/builtins.md): the pipeline steps (whether each keeps`,
    `${c} its rows as they are, and whether it sorts), where each regex builtin takes`,
    `${c} its pattern and its flags, how the SQL translators type a builtin's`,
    `${c} arguments (numeric positions; whether a BIN or a BOOL argument is accepted),`,
    `${c} and the builtins whose result is a list. Hosts classify through these`,
    `${c} rather than keeping lists of their own.`,
  ];
}

function renderJs(entries) {
  const lines = [
    `// ${HEADER}`,
    '//',
    '// One frozen record per builtin: min, max (Infinity when variadic), lazy,',
    '// binds, and the extra arity rule ({ parity, message } or { allowed, message })',
    '// or null. registry.mjs checks every define() against it.',
    '',
    'export const BUILTIN_MANIFEST = Object.freeze({',
  ];
  for (const e of entries) {
    let rule = 'null';
    if (e.parity) rule = `{ parity: ${jsStr(e.parity)}, message: ${jsStr(e.message)} }`;
    else if (e.allowed) rule = `{ allowed: [${e.allowed.join(', ')}], message: ${jsStr(e.message)} }`;
    lines.push(`  ${e.name}: { min: ${e.min}, max: ${e.max === null ? 'Infinity' : e.max}, lazy: ${e.lazy}, binds: ${e.binds}, arity: ${rule} },`);
  }
  lines.push('});', '',
    '// The binding forms (spec/builtins.md): per accepted count, in the order the',
    '// evaluator tries them, each argument\'s scope (outer | binder | inner), an',
    '// optional guard { arg, is: \'name\' | \'text\' } and the implicit names bound',
    '// inside. registry.mjs turns these into bindingForm().',
    'export const BINDING_FORMS = Object.freeze({');
  for (const e of entries) {
    if (!e.forms) continue;
    const fs = e.forms.map((f) => `{ scopes: [${f.roles.map((r) => jsStr(scopeOf(r))).join(', ')}], when: ${f.when ? `{ arg: ${f.when.arg}, is: ${jsStr(f.when.is)} }` : 'null'}, binds: [${f.binds.map(jsStr).join(', ')}] }`);
    lines.push(`  ${e.name}: [`, ...fs.map((s) => `    ${s},`), '  ],');
  }
  lines.push('});', '', ...classificationComment('//'),
    'export const PIPELINE_STEPS = Object.freeze({');
  for (const e of entries) if (e.pipeline) lines.push(`  ${e.name}: Object.freeze({ keepsRows: ${e.pipeline.keepsRows}, sorts: ${e.pipeline.sorts} }),`);
  lines.push('});', '', 'export const REGEX_CALLS = Object.freeze({');
  for (const e of entries) if (e.regex) lines.push(`  ${e.name}: Object.freeze({ pattern: ${e.regex.pattern}, flags: ${e.regex.flags} }),`);
  lines.push('});', '', 'export const SQL_ARGS = Object.freeze({');
  for (const e of entries) {
    if (!e.sql) continue;
    const n = e.sql.numeric === null ? 'null' : e.sql.numeric === 'all' ? "'all'" : `Object.freeze([${e.sql.numeric.join(', ')}])`;
    lines.push(`  ${e.name}: Object.freeze({ numeric: ${n}, bin: ${e.sql.bin}, bool: ${e.sql.bool} }),`);
  }
  lines.push('});', '', `export const YIELDS_LIST = Object.freeze(new Set([${entries.filter((e) => e.yieldsList).map((e) => jsStr(e.name)).join(', ')}]));`, '');
  return lines.join('\n');
}

function renderPython(entries) {
  const lines = [
    `# ${HEADER}`,
    '#',
    '# One tuple per builtin: (min, max, lazy, binds, rule) with max INF when',
    "# variadic and rule None, ('parity', 'odd'|'even', message) or",
    "# ('allowed', (counts...), message). registry.py checks every define() against it.",
    '',
    'INF = float(\'inf\')',
    '',
    'BUILTIN_MANIFEST = {',
  ];
  for (const e of entries) {
    let rule = 'None';
    if (e.parity) rule = `('parity', ${pyStr(e.parity)}, ${pyStr(e.message)})`;
    else if (e.allowed) rule = `('allowed', (${e.allowed.join(', ')}), ${pyStr(e.message)})`;
    lines.push(`    ${pyStr(e.name)}: (${e.min}, ${e.max === null ? 'INF' : e.max}, ${e.lazy ? 'True' : 'False'}, ${e.binds ? 'True' : 'False'}, ${rule}),`);
  }
  lines.push('}', '',
    '# The binding forms (spec/builtins.md): per accepted count, in the order the',
    "# evaluator tries them, (scopes, when, binds) with scopes a tuple of",
    "# 'outer' | 'binder' | 'inner', when None or (arg, 'name' | 'text'), and binds",
    '# the implicit names bound inside. registry.py turns these into binding_form().',
    'BINDING_FORMS = {');
  for (const e of entries) {
    if (!e.forms) continue;
    const fs = e.forms.map((f) => `((${f.roles.map((r) => pyStr(scopeOf(r))).join(', ')}${f.roles.length === 1 ? ',' : ''}), ${f.when ? `(${f.when.arg}, ${pyStr(f.when.is)})` : 'None'}, (${f.binds.map(pyStr).join(', ')}${f.binds.length === 1 ? ',' : ''}))`);
    lines.push(`    ${pyStr(e.name)}: (`, ...fs.map((s) => `        ${s},`), '    ),');
  }
  lines.push('}', '', ...classificationComment('#'),
    '# PIPELINE_STEPS: name -> (keeps_rows, sorts). REGEX_CALLS: name -> (pattern,',
    "# flags). SQL_ARGS: name -> (numeric, bin, bool), numeric a tuple of indexes,",
    "# 'all' or None.",
    'PIPELINE_STEPS = {');
  const pyb = (b) => (b ? 'True' : 'False');
  for (const e of entries) if (e.pipeline) lines.push(`    ${pyStr(e.name)}: (${pyb(e.pipeline.keepsRows)}, ${pyb(e.pipeline.sorts)}),`);
  lines.push('}', '', 'REGEX_CALLS = {');
  for (const e of entries) if (e.regex) lines.push(`    ${pyStr(e.name)}: (${e.regex.pattern}, ${e.regex.flags}),`);
  lines.push('}', '', 'SQL_ARGS = {');
  for (const e of entries) {
    if (!e.sql) continue;
    const n = e.sql.numeric === null ? 'None' : e.sql.numeric === 'all' ? "'all'" : `(${e.sql.numeric.join(', ')}${e.sql.numeric.length === 1 ? ',' : ''})`;
    lines.push(`    ${pyStr(e.name)}: (${n}, ${pyb(e.sql.bin)}, ${pyb(e.sql.bool)}),`);
  }
  lines.push('}', '', `YIELDS_LIST = frozenset((${entries.filter((e) => e.yieldsList).map((e) => pyStr(e.name)).join(', ')}))`, '');
  return lines.join('\n');
}

function renderPhp(entries) {
  const lines = [
    '<?php',
    `// ${HEADER}`,
    '//',
    '// One row per builtin: [min, max, lazy, binds, rule] with max PHP_INT_MAX when',
    "// variadic and rule null, ['parity', 'odd'|'even', message] or",
    "// ['allowed', [counts...], message]. Registry::define checks every definition",
    '// against it.',
    '',
    'declare(strict_types=1);',
    '',
    'namespace Sel;',
    '',
    'final class BuiltinManifest',
    '{',
    '    /** @var array<string, array{0:int,1:int,2:bool,3:bool,4:array<int,mixed>|null}> */',
    '    public const BUILTINS = [',
  ];
  for (const e of entries) {
    let rule = 'null';
    if (e.parity) rule = `['parity', ${phpStr(e.parity)}, ${phpStr(e.message)}]`;
    else if (e.allowed) rule = `['allowed', [${e.allowed.join(', ')}], ${phpStr(e.message)}]`;
    lines.push(`        ${phpStr(e.name)} => [${e.min}, ${e.max === null ? 'PHP_INT_MAX' : e.max}, ${e.lazy}, ${e.binds}, ${rule}],`);
  }
  lines.push('    ];', '',
    '    /**',
    '     * The binding forms (spec/builtins.md): per accepted count, in the order',
    "     * the evaluator tries them, [scopes, when, binds] with scopes a list of",
    "     * 'outer' | 'binder' | 'inner', when null or [arg, 'name' | 'text'], and",
    '     * binds the implicit names bound inside. Registry::bindingForm reads it.',
    '     *',
    '     * @var array<string, list<array{0:list<string>,1:array{0:int,1:string}|null,2:list<string>}>>',
    '     */',
    '    public const FORMS = [');
  for (const e of entries) {
    if (!e.forms) continue;
    const fs = e.forms.map((f) => `[[${f.roles.map((r) => phpStr(scopeOf(r))).join(', ')}], ${f.when ? `[${f.when.arg}, ${phpStr(f.when.is)}]` : 'null'}, [${f.binds.map(phpStr).join(', ')}]]`);
    lines.push(`        ${phpStr(e.name)} => [`, ...fs.map((s) => `            ${s},`), '        ],');
  }
  lines.push('    ];', '', ...classificationComment('    //'),
    "    /** @var array<string, array{0:bool,1:bool}> name => [keepsRows, sorts] */",
    '    public const PIPELINE_STEPS = [');
  for (const e of entries) if (e.pipeline) lines.push(`        ${phpStr(e.name)} => [${e.pipeline.keepsRows}, ${e.pipeline.sorts}],`);
  lines.push('    ];', '', "    /** @var array<string, array{0:int,1:int}> name => [pattern, flags] */", '    public const REGEX_CALLS = [');
  for (const e of entries) if (e.regex) lines.push(`        ${phpStr(e.name)} => [${e.regex.pattern}, ${e.regex.flags}],`);
  lines.push('    ];', '',
    "    /** @var array<string, array{0:list<int>|string|null,1:bool,2:bool}> name => [numeric ('all', indexes or null), bin, bool] */",
    '    public const SQL_ARGS = [');
  for (const e of entries) {
    if (!e.sql) continue;
    const n = e.sql.numeric === null ? 'null' : e.sql.numeric === 'all' ? "'all'" : `[${e.sql.numeric.join(', ')}]`;
    lines.push(`        ${phpStr(e.name)} => [${n}, ${e.sql.bin}, ${e.sql.bool}],`);
  }
  lines.push('    ];', '', '    /** @var array<string, true> */', '    public const YIELDS_LIST = [');
  for (const e of entries) if (e.yieldsList) lines.push(`        ${phpStr(e.name)} => true,`);
  lines.push('    ];', '}', '');
  return lines.join('\n');
}

function renderCpp(entries) {
  const lines = [
    `// ${HEADER}`,
    '//',
    '// One entry per builtin, sorted by name so lookup can bisect: min, max (-1',
    '// when variadic — the includer maps it to its own sentinel), lazy, binds and',
    '// the extra arity rule as a plain function, or nullptr. sel.cpp checks every',
    '// define() against it.',
    '#pragma once',
    '',
    '#include <string>',
    '',
    'namespace sel_builtin_manifest {',
    '',
    'struct Entry {',
    '  const char* name;',
    '  int min;',
    '  int max;',
    '  bool lazy;',
    '  bool binds;',
    '  std::string (*arity_error)(int);',
    '};',
    '',
  ];
  for (const e of entries) {
    if (!e.parity && !e.allowed) continue;
    const [before, after] = e.message.split('{count}');
    const test = e.parity
      ? `n % 2 ${e.parity === 'odd' ? '== 0' : '!= 0'}`
      : `!(${e.allowed.map((c) => `n == ${c}`).join(' || ')})`;
    lines.push(
      `inline std::string arity_${e.name}(int n) {`,
      `  if (${test}) return ${cppStr(before)} + std::to_string(n) + ${cppStr(after)};`,
      '  return "";',
      '}',
      '',
    );
  }
  lines.push('inline const Entry ENTRIES[] = {');
  for (const e of entries) {
    const rule = e.parity || e.allowed ? `arity_${e.name}` : 'nullptr';
    lines.push(`  {${cppStr(e.name)}, ${e.min}, ${e.max === null ? -1 : e.max}, ${e.lazy}, ${e.binds}, ${rule}},`);
  }
  lines.push('};', '', `inline constexpr int COUNT = ${entries.length};`, '');
  lines.push(
    '// The binding forms (spec/builtins.md): per accepted count, in the order the',
    '// evaluator tries them, each argument\'s scope, an optional guard on one',
    '// argument (kind 0 = none, 1 = a bare name, 2 = a text literal) and the',
    '// implicit names bound inside. sel.cpp turns these into binding_form().',
    "enum class Scope : unsigned char { Outer, Binder, Inner };",
    '',
    'struct Form {',
    '  const char* name;',
    '  int count;',
    '  Scope scopes[5];',
    '  int when_arg;        // -1 when unguarded',
    '  int when_kind;       // 1 name, 2 text',
    '  const char* binds[4];',
    '  int bind_count;',
    '};',
    '',
    'inline const Form FORMS[] = {');
  let formCount = 0;
  for (const e of entries) {
    if (!e.forms) continue;
    for (const f of e.forms) {
      const scopes = f.roles.map((r) => `Scope::${{ outer: 'Outer', binder: 'Binder', inner: 'Inner' }[scopeOf(r)]}`);
      while (scopes.length < 5) scopes.push('Scope::Outer');
      const binds = f.binds.map(cppStr);
      while (binds.length < 4) binds.push('nullptr');
      lines.push(`  {${cppStr(e.name)}, ${f.roles.length}, {${scopes.join(', ')}}, ${f.when ? f.when.arg : -1}, ${f.when ? (f.when.is === 'name' ? 1 : 2) : 0}, {${binds.join(', ')}}, ${f.binds.length}},`);
      formCount++;
    }
  }
  lines.push('};', '', `inline constexpr int FORM_COUNT = ${formCount};`, '', ...classificationComment('//'),
    'struct PipelineStep {', '  const char* name;', '  bool keeps_rows;', '  bool sorts;', '};', '',
    'inline const PipelineStep PIPELINE_STEPS[] = {');
  const steps = entries.filter((e) => e.pipeline);
  for (const e of steps) lines.push(`  {${cppStr(e.name)}, ${e.pipeline.keepsRows}, ${e.pipeline.sorts}},`);
  lines.push('};', '', `inline constexpr int PIPELINE_STEP_COUNT = ${steps.length};`, '',
    'struct RegexCall {', '  const char* name;', '  int pattern;', '  int flags;', '};', '',
    'inline const RegexCall REGEX_CALLS[] = {');
  const rx = entries.filter((e) => e.regex);
  for (const e of rx) lines.push(`  {${cppStr(e.name)}, ${e.regex.pattern}, ${e.regex.flags}},`);
  lines.push('};', '', `inline constexpr int REGEX_CALL_COUNT = ${rx.length};`, '',
    '// numeric_all: every argument is a number; otherwise numeric[0..numeric_count).',
    'struct SqlArgs {', '  const char* name;', '  bool numeric_all;', '  int numeric[4];', '  int numeric_count;', '  bool bin;', '  bool boolean;', '};', '',
    'inline const SqlArgs SQL_ARGS[] = {');
  const sq = entries.filter((e) => e.sql);
  for (const e of sq) {
    const list = Array.isArray(e.sql.numeric) ? e.sql.numeric : [];
    if (list.length > 4) fail(`${e.name}.sql.numericArgs: the C++ rendering holds four`);
    const padded = [...list]; while (padded.length < 4) padded.push(-1);
    lines.push(`  {${cppStr(e.name)}, ${e.sql.numeric === 'all'}, {${padded.join(', ')}}, ${list.length}, ${e.sql.bin}, ${e.sql.bool}},`);
  }
  lines.push('};', '', `inline constexpr int SQL_ARGS_COUNT = ${sq.length};`, '');
  const yl = entries.filter((e) => e.yieldsList);
  lines.push(`inline const char* const YIELDS_LIST[] = {${yl.map((e) => cppStr(e.name)).join(', ')}};`, '',
    `inline constexpr int YIELDS_LIST_COUNT = ${yl.length};`, '', '}  // namespace sel_builtin_manifest', '');
  return lines.join('\n');
}

function renderLisp(entries) {
  const lines = [
    `;;;; ${HEADER}`,
    ';;;;',
    ';;;; One list per builtin: (name min max lazy binds rule), max :VARIADIC when',
    ';;;; variadic and rule NIL, (:parity :odd|:even message) or',
    ';;;; (:allowed (counts...) message). registry.lisp checks every DEFINE-BUILTIN',
    ';;;; against it.',
    '',
    '(in-package #:sel)',
    '',
    '(setf *builtin-manifest-data*',
    "      '(",
  ];
  for (const e of entries) {
    let rule = 'nil';
    if (e.parity) rule = `(:parity :${e.parity} ${lispStr(e.message)})`;
    else if (e.allowed) rule = `(:allowed (${e.allowed.join(' ')}) ${lispStr(e.message)})`;
    lines.push(`        (${lispStr(e.name)} ${e.min} ${e.max === null ? ':variadic' : e.max} ${e.lazy ? 't' : 'nil'} ${e.binds ? 't' : 'nil'} ${rule})`);
  }
  lines[lines.length - 1] += '))';
  lines.push('',
    ';;;; The binding forms (spec/builtins.md): per accepted count, in the order the',
    ';;;; evaluator tries them, (name scopes when binds) with scopes a list of',
    ';;;; :outer | :binder | :inner, when NIL or (arg :name|:text), and binds the',
    ';;;; implicit names bound inside. registry.lisp turns these into BINDING-FORM.',
    '',
    '(setf *builtin-form-data*',
    "      '(");
  for (const e of entries) {
    if (!e.forms) continue;
    for (const f of e.forms) {
      lines.push(`        (${lispStr(e.name)} (${f.roles.map((r) => ':' + scopeOf(r)).join(' ')}) ${f.when ? `(${f.when.arg} :${f.when.is})` : 'nil'} (${f.binds.map(lispStr).join(' ')}))`);
    }
  }
  lines[lines.length - 1] += '))';
  lines.push('', ...classificationComment(';;;;'),
    ';;;; *BUILTIN-PIPELINE-DATA*: (name keeps-rows sorts). *BUILTIN-REGEX-DATA*:',
    ';;;; (name pattern flags). *BUILTIN-SQL-ARG-DATA*: (name numeric bin bool),',
    ';;;; numeric a list of indexes, :ALL or NIL. *BUILTIN-YIELDS-LIST*: names.', '',
    '(defparameter *builtin-pipeline-data*', "  '(");
  const lb = (b) => (b ? 't' : 'nil');
  for (const e of entries) if (e.pipeline) lines.push(`    (${lispStr(e.name)} ${lb(e.pipeline.keepsRows)} ${lb(e.pipeline.sorts)})`);
  lines[lines.length - 1] += '))';
  lines.push('', '(defparameter *builtin-regex-data*', "  '(");
  for (const e of entries) if (e.regex) lines.push(`    (${lispStr(e.name)} ${e.regex.pattern} ${e.regex.flags})`);
  lines[lines.length - 1] += '))';
  lines.push('', '(defparameter *builtin-sql-arg-data*', "  '(");
  for (const e of entries) {
    if (!e.sql) continue;
    const n = e.sql.numeric === null ? 'nil' : e.sql.numeric === 'all' ? ':all' : `(${e.sql.numeric.join(' ')})`;
    lines.push(`    (${lispStr(e.name)} ${n} ${lb(e.sql.bin)} ${lb(e.sql.bool)})`);
  }
  lines[lines.length - 1] += '))';
  lines.push('', `(defparameter *builtin-yields-list* '(${entries.filter((e) => e.yieldsList).map((e) => lispStr(e.name)).join(' ')}))`, '');
  return lines.join('\n');
}

function arityText(e) {
  if (e.allowed) return e.allowed.join(' or ');
  const range = e.max === null ? `${e.min}+` : e.min === e.max ? `${e.min}` : `${e.min}–${e.max}`;
  return e.parity ? `${range}, ${e.parity}` : range;
}

function renderDocs(entries) {
  const lines = [
    `<!-- ${HEADER} -->`,
    '# Builtins',
    '',
    'Every SEL builtin, from the authored manifest `spec/builtins.json` (format:',
    '`spec/builtins.md`). *Arguments* is the accepted count; *Evaluates* says',
    'whether the function receives values (strict) or argument nodes (lazy), and',
    'whether it introduces an element binder. The section is where `spec/SPEC.md`',
    'defines the semantics; this table only says what the function table knows.',
    '',
    '| Name | Signature | Arguments | Evaluates | Spec |',
    '|---|---|---|---|---|',
  ];
  for (const e of entries) {
    const sig = e.signatures.map((s) => '`' + s + '`').join('<br>');
    const how = e.binds ? 'lazy, binds' : e.lazy ? 'lazy' : 'strict';
    lines.push(`| \`${e.name}\` | ${sig} | ${arityText(e)} | ${how} | ${e.spec} |`);
  }
  lines.push('', '## Binding forms', '',
    'For each binding builtin, the accepted argument lists in the order the',
    'evaluator tries them. *outer* arguments are evaluated where the call is;',
    'a *binder* is a bare name, not evaluated; *body*, *key*, *proj* and *pred*',
    'run once per element with the listed names bound (plus every binder). A',
    'guard says which form a count takes when two would fit.', '',
    '| Name | Arguments | Guard | Bound inside |', '|---|---|---|---|');
  for (const e of entries) {
    if (!e.forms) continue;
    for (const f of e.forms) {
      const guard = f.when ? `argument ${f.when.arg + 1} is a ${f.when.is === 'name' ? 'bare name' : 'text literal'}` : '';
      lines.push(`| \`${e.name}\` | ${f.roles.join(', ')} | ${guard} | ${f.binds.map((b) => '`' + b + '`').join(' ')} |`);
    }
  }
  const lazy = entries.filter((e) => e.lazy).length;
  const binds = entries.filter((e) => e.binds).length;
  const rules = entries.filter((e) => e.parity || e.allowed).map((e) => '`' + e.name + '`').join(', ');
  const names = (pick) => entries.filter(pick).map((e) => '`' + e.name + '`').join(' ');
  lines.push('', '## Classification', '',
    'Facts the evaluator, optimiser, planners and translators classify builtins by.', '',
    '| Class | Builtins |', '|---|---|',
    `| pipeline steps (\`.>\` chains them; the first argument is the rows) | ${names((e) => e.pipeline)} |`,
    `| steps that keep their rows as they are (fewer, or reordered) | ${names((e) => e.pipeline && e.pipeline.keepsRows)} |`,
    `| steps that sort | ${names((e) => e.pipeline && e.pipeline.sorts)} |`,
    `| result is a list | ${names((e) => e.yieldsList)} |`, '',
    '| Regex builtin | Pattern argument | Flags argument |', '|---|---|---|');
  for (const e of entries) if (e.regex) lines.push(`| \`${e.name}\` | ${e.regex.pattern + 1} | ${e.regex.flags + 1} |`);
  lines.push('', 'How the SQL translators type arguments (`sql`): which must be numbers, and',
    'which builtins take a BIN or a BOOL argument rather than refusing it.', '',
    '| Builtin | Numeric arguments | BIN accepted | BOOL accepted |', '|---|---|---|---|');
  for (const e of entries) {
    if (!e.sql) continue;
    const n = e.sql.numeric === null ? '' : e.sql.numeric === 'all' ? 'all' : e.sql.numeric.map((i) => i + 1).join(', ');
    lines.push(`| \`${e.name}\` | ${n} | ${e.sql.bin ? 'yes' : ''} | ${e.sql.bool ? 'yes' : ''} |`);
  }
  lines.push('', `${entries.length} builtins: ${lazy} lazy, of which ${binds} bind; extra arity rules on ${rules}.`, '');
  return lines.join('\n');
}

function renderGo(entries) {
  const lines = [
    `// ${HEADER}`,
    '//',
    '// One entry per builtin: min, max (-1 when variadic), lazy, binds, and',
    '// the extra arity rule as a validator function or nil.',
    '',
    'package manifest',
    '',
    'import "fmt"',
    '',
    'type Entry struct {',
    '\tName       string',
    '\tMin        int',
    '\tMax        int // -1 when variadic',
    '\tLazy       bool',
    '\tBinds      bool',
    '\tArityError func(n int) string',
    '}',
    '',
    'type Scope uint8',
    '',
    'const (',
    '\tScopeOuter Scope = iota',
    '\tScopeBinder',
    '\tScopeInner',
    ')',
    '',
    'type WhenKind uint8',
    '',
    'const (',
    '\tWhenNone WhenKind = iota',
    '\tWhenName',
    '\tWhenText',
    ')',
    '',
    '// Role is what one argument of a form is (spec/builtins.md, "Binding forms").',
    'type Role uint8',
    '',
    'const (',
    '\tRoleSource Role = iota',
    '\tRoleOuter',
    '\tRoleBinder',
    '\tRoleBody',
    '\tRoleKey',
    '\tRoleProj',
    '\tRolePred',
    ')',
    '',
    'type Form struct {',
    '\tName     string',
    '\tCount    int',
    '\tScopes   []Scope',
    '\tRoles    []Role',
    '\tWhenArg  int',
    '\tWhenKind WhenKind',
    '\tBinds    []string',
    '}',
    '',
  ];

  for (const e of entries) {
    if (!e.parity && !e.allowed) continue;
    const [before, after] = e.message.split('{count}');
    // gofmt's spacing: no blanks around % inside a comparison.
    const test = e.parity
      ? `n%2 ${e.parity === 'odd' ? '== 0' : '!= 0'}`
      : `!(${e.allowed.map((c) => `n == ${c}`).join(' || ')})`;
    lines.push(
      `func arity_${e.name}(n int) string {`,
      `\tif ${test} {`,
      `\t\treturn fmt.Sprintf("%s%d%s", ${JSON.stringify(before)}, n, ${JSON.stringify(after)})`,
      '\t}',
      '\treturn ""',
      '}',
      '',
    );
  }

  // gofmt aligns the values of one-line map entries one space past the longest key.
  lines.push('var Builtins = map[string]Entry{');
  const keyW = Math.max(...entries.map((e) => e.name.length)) + 3;
  for (const e of entries) {
    const rule = e.parity || e.allowed ? `arity_${e.name}` : 'nil';
    lines.push(`\t${`"${e.name}":`.padEnd(keyW)} {Name: "${e.name}", Min: ${e.min}, Max: ${e.max === null ? -1 : e.max}, Lazy: ${e.lazy}, Binds: ${e.binds}, ArityError: ${rule}},`);
  }
  lines.push('}', '', 'var BindingForms = map[string][]Form{');
  for (const e of entries) {
    if (!e.forms) continue;
    lines.push(`\t"${e.name}": {`);
    for (const f of e.forms) {
      const scopes = f.roles.map((r) => `Scope${{ outer: 'Outer', binder: 'Binder', inner: 'Inner' }[scopeOf(r)]}`);
      const whenArg = f.when ? f.when.arg : -1;
      const whenKind = f.when ? (f.when.is === 'name' ? 'WhenName' : 'WhenText') : 'WhenNone';
      const binds = f.binds.map((b) => JSON.stringify(b)).join(', ');
      const roles = f.roles.map((r) => `Role${r[0].toUpperCase()}${r.slice(1)}`);
      lines.push(`\t\t{Name: "${e.name}", Count: ${f.roles.length}, Scopes: []Scope{${scopes.join(', ')}}, Roles: []Role{${roles.join(', ')}}, WhenArg: ${whenArg}, WhenKind: ${whenKind}, Binds: []string{${binds}}},`);
    }
    lines.push('\t},');
  }
  lines.push('}', '', ...classificationComment('//'),
    'type PipelineStep struct {', '\tKeepsRows bool', '\tSorts     bool', '}', '',
    'var PipelineSteps = map[string]PipelineStep{');
  // Each map pads its own keys as gofmt does (see Builtins above).
  const goKey = (subset) => { const w = Math.max(...subset.map((e) => e.name.length)) + 3; return (e) => `"${e.name}":`.padEnd(w); };
  const piped = entries.filter((e) => e.pipeline), pipeKey = goKey(piped);
  for (const e of piped) lines.push(`\t${pipeKey(e)} {KeepsRows: ${e.pipeline.keepsRows}, Sorts: ${e.pipeline.sorts}},`);
  lines.push('}', '', 'type RegexCall struct {', '\tPattern int', '\tFlags   int', '}', '', 'var RegexCalls = map[string]RegexCall{');
  const regexed = entries.filter((e) => e.regex), regexKey = goKey(regexed);
  for (const e of regexed) lines.push(`\t${regexKey(e)} {Pattern: ${e.regex.pattern}, Flags: ${e.regex.flags}},`);
  lines.push('}', '',
    '// SQLArgs: NumericAll when every argument is a number, else the Numeric indexes.',
    'type SQLArgs struct {', '\tNumericAll bool', '\tNumeric    []int', '\tBin        bool', '\tBool       bool', '}', '',
    'var SQLArgTypes = map[string]SQLArgs{');
  const typed = entries.filter((e) => e.sql), sqlKey = goKey(typed);
  for (const e of typed) {
    const list = Array.isArray(e.sql.numeric) ? `[]int{${e.sql.numeric.join(', ')}}` : 'nil';
    lines.push(`\t${sqlKey(e)} {NumericAll: ${e.sql.numeric === 'all'}, Numeric: ${list}, Bin: ${e.sql.bin}, Bool: ${e.sql.bool}},`);
  }
  lines.push('}', '', 'var YieldsList = map[string]bool{');
  const lists = entries.filter((e) => e.yieldsList), listKey = goKey(lists);
  for (const e of lists) lines.push(`\t${listKey(e)} true,`);
  lines.push('}', '');
  return lines.join('\n');
}

function renderRust(entries) {
  const lines = [
    `// ${HEADER}`,
    '//',
    '// One entry per builtin: min, max (None when variadic), lazy, binds, and',
    '// the extra arity rule as a validator function or None.',
    '',
    '#![allow(non_snake_case, unpredictable_function_pointer_comparisons)]',
    '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]',
    'pub struct Entry {',
    '    pub name: &\'static str,',
    '    pub min: usize,',
    '    pub max: Option<usize>,',
    '    pub lazy: bool,',
    '    pub binds: bool,',
    '    pub arity_error: Option<fn(usize) -> Option<String>>,',
    '}',
    '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]',
    'pub enum Scope {',
    '    Outer,',
    '    Binder,',
    '    Inner,',
    '}',
    '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]',
    'pub enum WhenKind {',
    '    None,',
    '    Name,',
    '    Text,',
    '}',
    '',
    '/// What one argument of a form is (spec/builtins.md, "Binding forms").',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]',
    'pub enum Role {',
    '    Source,',
    '    Outer,',
    '    Binder,',
    '    Body,',
    '    Key,',
    '    Proj,',
    '    Pred,',
    '}',
    '',
    '#[derive(Clone, Debug)]',
    'pub struct Form {',
    '    pub name: &\'static str,',
    '    pub count: usize,',
    '    pub scopes: &\'static [Scope],',
    '    pub roles: &\'static [Role],',
    '    pub when_arg: Option<usize>,',
    '    pub when_kind: WhenKind,',
    '    pub binds: &\'static [&\'static str],',
    '}',
    '',
  ];

  for (const e of entries) {
    if (!e.parity && !e.allowed) continue;
    const [before, after] = e.message.split('{count}');
    const test = e.parity
      ? `n % 2 ${e.parity === 'odd' ? '== 0' : '!= 0'}`
      : `!(${e.allowed.map((c) => `n == ${c}`).join(' || ')})`;
    lines.push(
      `fn arity_${e.name}(n: usize) -> Option<String> {`,
      `    if ${test} {`,
      `        Some(format!("{}{}{}", ${JSON.stringify(before)}, n, ${JSON.stringify(after)}))`,
      '    } else {',
      '        None',
      '    }',
      '}',
      '',
    );
  }

  lines.push('pub const BUILTINS: &[(&str, Entry)] = &[');
  for (const e of entries) {
    const rule = e.parity || e.allowed ? `Some(arity_${e.name})` : 'None';
    const maxVal = e.max === null ? 'None' : `Some(${e.max})`;
    lines.push(`    ("${e.name}", Entry { name: "${e.name}", min: ${e.min}, max: ${maxVal}, lazy: ${e.lazy}, binds: ${e.binds}, arity_error: ${rule} }),`);
  }
  lines.push('];', '', 'pub const BINDING_FORMS: &[(&str, &[Form])] = &[');
  for (const e of entries) {
    if (!e.forms) continue;
    lines.push(`    ("${e.name}", &[`);
    for (const f of e.forms) {
      const scopes = f.roles.map((r) => `Scope::${{ outer: 'Outer', binder: 'Binder', inner: 'Inner' }[scopeOf(r)]}`);
      const whenArg = f.when ? `Some(${f.when.arg})` : 'None';
      const whenKind = f.when ? (f.when.is === 'name' ? 'WhenKind::Name' : 'WhenKind::Text') : 'WhenKind::None';
      const binds = f.binds.map((b) => JSON.stringify(b)).join(', ');
      const roles = f.roles.map((r) => `Role::${r[0].toUpperCase()}${r.slice(1)}`);
      lines.push(`        Form { name: "${e.name}", count: ${f.roles.length}, scopes: &[${scopes.join(', ')}], roles: &[${roles.join(', ')}], when_arg: ${whenArg}, when_kind: ${whenKind}, binds: &[${binds}] },`);
    }
    lines.push('    ]),');
  }
  lines.push('];', '', ...classificationComment('//'),
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]', 'pub struct PipelineStep {', '    pub keeps_rows: bool,', '    pub sorts: bool,', '}', '',
    'pub const PIPELINE_STEPS: &[(&str, PipelineStep)] = &[');
  for (const e of entries) if (e.pipeline) lines.push(`    ("${e.name}", PipelineStep { keeps_rows: ${e.pipeline.keepsRows}, sorts: ${e.pipeline.sorts} }),`);
  lines.push('];', '', '/// A pipeline step by name, as a match: no table walk per call.',
    'pub fn pipeline_step(name: &str) -> Option<PipelineStep> {', '    match name {');
  for (const e of entries) if (e.pipeline) lines.push(`        "${e.name}" => Some(PipelineStep { keeps_rows: ${e.pipeline.keepsRows}, sorts: ${e.pipeline.sorts} }),`);
  lines.push('        _ => None,', '    }', '}', '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]', 'pub struct RegexCall {', '    pub pattern: usize,', '    pub flags: usize,', '}', '',
    'pub fn regex_call(name: &str) -> Option<RegexCall> {', '    match name {');
  for (const e of entries) if (e.regex) lines.push(`        "${e.name}" => Some(RegexCall { pattern: ${e.regex.pattern}, flags: ${e.regex.flags} }),`);
  lines.push('        _ => None,', '    }', '}', '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]', 'pub enum NumericArgs {', '    None,', '    All,', "    At(&'static [usize]),", '}', '',
    '#[derive(Clone, Copy, Debug, PartialEq, Eq)]', 'pub struct SqlArgs {', '    pub numeric: NumericArgs,', '    pub bin_arg: bool,', '    pub bool_arg: bool,', '}', '',
    'pub const SQL_ARGS: &[(&str, SqlArgs)] = &[');
  for (const e of entries) {
    if (!e.sql) continue;
    const n = e.sql.numeric === null ? 'NumericArgs::None' : e.sql.numeric === 'all' ? 'NumericArgs::All' : `NumericArgs::At(&[${e.sql.numeric.join(', ')}])`;
    lines.push(`    ("${e.name}", SqlArgs { numeric: ${n}, bin_arg: ${e.sql.bin}, bool_arg: ${e.sql.bool} }),`);
  }
  lines.push('];', '', 'pub fn sql_args(name: &str) -> Option<SqlArgs> {',
    '    SQL_ARGS.iter().find(|(n, _)| *n == name).map(|(_, a)| *a)', '}', '',
    'pub const YIELDS_LIST: &[&str] = &[');
  for (const e of entries) if (e.yieldsList) lines.push(`    "${e.name}",`);
  lines.push('];', '', 'pub fn yields_list(name: &str) -> bool {', '    YIELDS_LIST.contains(&name)', '}', '');
  return lines.join('\n');
}

// ---------------------------------------------------------------------------

const entries = load();
const rendered = {
  js: renderJs(entries), python: renderPython(entries), php: renderPhp(entries),
  cpp: renderCpp(entries), lisp: renderLisp(entries), go: renderGo(entries),
  rust: renderRust(entries), docs: renderDocs(entries),
};

writeOrCheck('gen-builtins', ROOT, Object.entries(OUTPUTS).map(([host, path]) => [path, rendered[host]]),
  { check, rerun: 'node tools/gen-builtins.mjs' });
if (check) process.stdout.write(`gen-builtins: ${entries.length} builtins, ${Object.keys(OUTPUTS).length} renderings current\n`);
